const recipeBy=id=>recipes.find(r=>r.id===id),productBy=id=>state.products.find(p=>p.id===id);
let state;try{state=JSON.parse(localStorage.getItem(STORAGE))}catch{};
function seed(){let products=rawProducts.map((r,i)=>({id:r[0],name:r[1],unit:r[2],min:r[4],zone:r[5],shelf:r[6],lots:[{id:'lot-'+i,qty:r[3],received:today(),expiry:future(r[7]),supplier:'Örnek açılış stoğu'}]}));let now=Date.now();return{version:1,products,jobs:[{id:uid(),recipe:'croissant',batches:1,stage:0,note:'Sabah vitrini',owner:'Pastane ekibi',created:now,started:null,stageAt:null,pausedAt:null,pausedTotal:0,stagePaused:0,checks:[],transitions:[]},{id:uid(),recipe:'cookie',batches:1,stage:1,note:'Günün kurabiyesi',owner:'Pastane ekibi',created:now,started:now,stageAt:now,pausedAt:null,pausedTotal:0,stagePaused:0,checks:[],transitions:[]},{id:uid(),recipe:'brownie',batches:1,stage:2,note:'Öğleden sonra vitrini',owner:'Pastane ekibi',created:now,started:now,stageAt:now,pausedAt:null,pausedTotal:0,stagePaused:0,checks:[],transitions:[]}],history:[],movements:[],menu:recipes.map(r=>r.id),stationChecks:{}}}
if(!state||state.version!==1)state=seed();let storageOK=true;function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Tarayıcı kaydı yapılamadı. Kayıtları indirerek çalışmanızı saklayın.')}}
const total=p=>p.lots.reduce((a,l)=>a+l.qty,0), expired=p=>p.lots.reduce((a,l)=>a+(l.expiry<today()?l.qty:0),0),usable=p=>Math.max(0,total(p)-expired(p));
const reserved=id=>state.jobs.reduce((a,j)=>a+(recipeBy(j.recipe)?.ingredients.find(x=>x[0]===id)?.[1]||0)*j.batches,0);
const available=p=>Math.max(0,usable(p)-reserved(p.id));
const lowProducts=()=>state.products.filter(p=>available(p)<p.min);
const soon=p=>p.lots.some(l=>l.qty>0&&l.expiry>=today()&&l.expiry<=future(3));
const qty=(n,u)=>{const f=x=>Number(x).toLocaleString('en-GB',{maximumFractionDigits:3});if(u==='g'&&n>=1000)return f(n/1000)+' kg';if(u==='ml'&&n>=1000)return f(n/1000)+' L';return f(n)+' '+u};
const statusOf=p=>expired(p)>0?'expired':available(p)<p.min?'low':soon(p)?'soon':'ok';
const badge=p=>{let s=statusOf(p);return `<span class="status ${s==='expired'?'bad':s==='low'||s==='soon'?'warn':''}">${{expired:'Tarihi geçmiş',low:'Düşük stok',soon:'Tarih yaklaşıyor',ok:'Yeterli'}[s]}</span>`};
const canMake=(r,b=1)=>r.ingredients.every(([id,q])=>available(productBy(id))+1e-6>=q*b);
const capacity=r=>Math.max(0,Math.floor(Math.min(...r.ingredients.map(([id,q])=>available(productBy(id))/q))));
const totalMinutes=r=>r.times.reduce((a,b)=>a+b,0)+r.rest;
const art=(r,extra='')=>`<div class="pastry-art ${extra}" style="--col:${recipes.indexOf(r)%4};--row:${Math.floor(recipes.indexOf(r)/4)}" role="img" aria-label="${esc(r.name)} — elde boyanmış pastane illüstrasyonu"></div>`;
const stages=['Planlandı','Hazırlanıyor','Fırında','Son dokunuş'];
const stageAreas=['Mal kabul','Hamur & hazırlık','Fırın & pişirme','Soğutma & süsleme'];
const navs=[['overview','Pastane özeti'],['stock','Stok & depo'],['recipes','Reçete defteri'],['prep','Hazırlık takibi'],['plan','Mutfak planı']];
let page='overview',search='',stockZone='Tümü',stockStatus='Tümü',recipeCat='Tümü',menuOnly=false,prepFilter='Tümü',selectedStation='',scaleBatches=1,currentRecipe=null,currentProduct=null;
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function navigate(p){if(!navs.some(n=>n[0]===p))p='overview';page=p;search='';stockZone='Tümü';stockStatus='Tümü';recipeCat='Tümü';menuOnly=false;prepFilter='Tümü';render();window.scrollTo({top:0,behavior:'instant'})}
function onRoute(){navigate(location.hash.slice(1)||'overview')}window.addEventListener('hashchange',onRoute);
function summary(items){return `<div class="summary">${items.map(x=>`<div class="summary-cell ${x[3]||''}"><span class="title">${x[0]}</span><strong class="num">${x[1]}</strong><span class="caption">${x[2]}</span></div>`).join('')}</div>`}
function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${action?'<div class="actions">'+action+'</div>':''}</div>`}
function recipeCards(list=recipes){if(!list.length)return'<div class="empty"><strong>Bu rafta henüz reçete yok.</strong>Aramayı veya kategori seçimini değiştir.</div>';return `<div class="recipe-grid">${list.map(r=>`<article class="recipe-card"><button class="pastry-art" style="--col:${recipes.indexOf(r)%4};--row:${Math.floor(recipes.indexOf(r)/4)}" data-action="recipe" data-id="${r.id}" aria-label="${r.name} reçetesini aç"><span class="recipe-category">${r.category.toLocaleUpperCase('en-GB')}</span>${state.menu.includes(r.id)?'<span class="on-menu">Vitrin menüsünde</span>':''}</button><div class="recipe-body"><h3>${r.name}</h3><p class="recipe-meta">${r.yield} ${r.unit} / parti &nbsp; · &nbsp; ${totalMinutes(r)} dk toplam</p><div class="recipe-bottom"><span class="status ${canMake(r)?'':'warn'}">${canMake(r)?capacity(r)+' parti üretilebilir':'Malzeme eksik'}</span><button class="link" data-action="recipe" data-id="${r.id}">Reçeteyi aç ↗</button></div></div></article>`).join('')}</div>`}
function overview(){let low=lowProducts();return `<span class="eyebrow">${dateLabel(today())} / PASTANE ATÖLYESİ</span><section class="hero"><div class="hero-copy"><span class="eyebrow">CULINARYFLOW · GÜNLÜK ÜRETİM</span><h1>Tezgâhtan<br>vitrine.</h1><p>Kat kat hamurlar, taze çıkan tepsiler.<br>Pastanenin reçeteleri, malzemeleri ve günlük üretimi bir arada.</p><button class="btn" data-action="new-job">＋ Üretim planla</button></div><div class="hero-art"><img src="patisserie-kitchen.png" alt="Krem, pembe ve yeşil tonlarında elde boyanmış pastane tezgâhı"></div></section>${summary([['Vitrin menüsü',state.menu.length,'12 pastane reçetesinden'],['Devam eden üretim',state.jobs.length,'Planlama, hazırlık ve fırın'],['Stok uyarısı',low.length,'Kullanılabilir miktara göre','warning'],['Tamamlanan parti',state.history.filter(j=>!j.cancelled).length,'Bu çalışma alanında']])}<div class="section-head"><h2>Bugünün tezgâhı</h2><a class="link" href="#prep">Üretim panosuna git ↗</a></div><div class="panel" style="padding-top:8px;padding-bottom:8px">${state.jobs.slice(0,4).map(j=>{let r=recipeBy(j.recipe);return `<div class="mini-row"><div class="upcoming">${art(r,'card-image-mini')}<div><b>${r.name}</b><small>${j.batches*r.yield} ${r.unit} · ${esc(j.note||'Vitrin üretimi')}</small></div></div><div class="actions"><span class="status ${j.stage===2?'warn':'info'}">${stages[j.stage]}</span><button class="link" data-action="job-detail" data-id="${j.id}">Detay ↗</button></div></div>`}).join('')||'<div class="empty">Yeni bir üretim planlayarak başla.</div>'}</div><div class="section-head"><h2>Pastanenin reçete defteri</h2><a class="link" href="#recipes">12 reçeteyi keşfet ↗</a></div>${recipeCards(recipes.filter(r=>state.menu.includes(r.id)).slice(0,4))}<div class="split-panels"><section class="panel"><div class="section-head" style="margin-top:0"><h2>Depoya bir bakış</h2><span class="status warn">${low.length} uyarı</span></div>${low.slice(0,3).map(p=>`<div class="mini-row"><div>${p.name}<small>${p.zone} · ${p.shelf}</small></div><button class="link" data-action="product" data-id="${p.id}">${qty(available(p),p.unit)} ↗</button></div>`).join('')||'<p>Tüm malzemeler stok sınırının üzerinde.</p>'}<p><a class="link" href="#stock">Stok ve depoyu yönet ↗</a></p></section><section class="panel olive"><span class="eyebrow">PASTANE ATÖLYESİ / ÇALIŞMA ALANLARI</span><h2 style="margin:18px 0">Hamurun da<br>bir yolu var.</h2><p>Mal kabulden kuru depoya, hazırlık tezgâhından fırına ve vitrine. Alanları aç, ilgili ürünleri ve işleri gör.</p><a class="btn light" style="display:inline-block;text-decoration:none" href="#plan">Atölye planını aç ↗</a></section></div>`}
function shelfCards(){return `<div class="shelf-grid">${zones.map((z,i)=>{let ps=state.products.filter(p=>p.zone===z);return `<button class="shelf-card ${stockZone===z?'selected':''}" data-action="zone-filter" data-id="${z}"><span class="shelf-head">${z}<span>${['▤','❄','❆'][i]}</span></span><span class="shelf-num">${ps.length} malzeme</span><p>${ps.filter(p=>statusOf(p)!=='ok').length} uyarı · ${['A1–A6 rafları','B1–B3 rafları','C1–C2 rafları'][i]}</p><p>İçindekileri gör →</p></button>`}).join('')}</div>`}
function filteredProducts(){return state.products.filter(p=>p.name.toLocaleLowerCase('en-GB').includes(search.toLocaleLowerCase('en-GB'))&&(stockZone==='Tümü'||stockZone===p.zone)&&(stockStatus==='Tümü'||stockStatus==='Düşük stok'&&available(p)<p.min||stockStatus==='Tarih yaklaşıyor'&&soon(p)||stockStatus==='Tarihi geçmiş'&&expired(p)>0))}
function stockRows(){let list=filteredProducts();return list.map(p=>{let first=p.lots.filter(l=>l.qty>0).sort((a,b)=>a.expiry.localeCompare(b.expiry))[0];let ratio=Math.min(100,p.min?available(p)/p.min*50:100);return `<tr><td data-label="Malzeme"><strong>${p.name}</strong><small>${p.shelf}</small></td><td data-label="Fiziksel stok">${qty(total(p),p.unit)}<small>${qty(reserved(p.id),p.unit)} ayrıldı</small></td><td data-label="Kullanılabilir"><strong>${qty(available(p),p.unit)}</strong><div class="stock-meter"><i class="${available(p)<p.min?'bad':''}" style="width:${ratio}%"></i></div><small>Alt sınır ${qty(p.min,p.unit)}</small></td><td data-label="Depolama & tarih">${p.zone}<small>${first?'En yakın tarih: '+dateLabel(first.expiry):'Stok yok'}</small></td><td data-label="Durum">${badge(p)}</td><td class="stock-action"><button class="link" data-action="product" data-id="${p.id}">Yönet ↗</button></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">Bu filtreyle eşleşen malzeme bulunamadı.</div></td></tr>'}
function movementsTable(limit=8){return state.movements.slice(0,limit).map(m=>`<tr><td>${timeLabel(m.at)}</td><td>${esc(productBy(m.product)?.name||m.product)}</td><td>${m.change>0?'+':''}${qty(m.change,productBy(m.product)?.unit||'')}</td><td>${esc(m.reason)}</td></tr>`).join('')||'<tr><td colspan="4">Mal kabul, sayım ve üretim hareketleri burada görünecek.</td></tr>'}
function stockView(){let reservedCount=state.products.filter(p=>reserved(p.id)>0).length;return heading('MALZEME & SAKLAMA','Pastanenin kileri.','Rafları, ayrılan malzemeleri ve son kullanım tarihlerini birlikte takip et.',`<button class="btn light" data-action="shopping-list">Eksik listesi ↗</button><button class="btn" data-action="receive">＋ Mal kabul</button>`)+summary([['Kayıtlı malzeme',state.products.length,'Üç depolama alanında'],['Düşük stok',lowProducts().length,'Üretime ayrılanlar çıkarıldı','warning'],['Yaklaşan tarih',state.products.filter(soon).length,'Önümüzdeki 3 gün içinde'],['Üretime ayrılan',reservedCount,'Malzeme türü rezerve edildi']])+shelfCards()+`<div class="toolbar"><input class="search" id="stock-search" aria-label="Stokta malzeme ara" placeholder="Un, tereyağı, krema…" value="${esc(search)}"><select id="stock-zone" aria-label="Depolama alanı"><option>Tümü</option>${zones.map(z=>`<option ${stockZone===z?'selected':''}>${z}</option>`).join('')}</select><select id="stock-status" aria-label="Stok durumu">${['Tümü','Düşük stok','Tarih yaklaşıyor','Tarihi geçmiş'].map(z=>`<option ${stockStatus===z?'selected':''}>${z}</option>`).join('')}</select><button class="link" data-action="clear-stock">Filtreleri temizle</button></div><div class="table-wrap inventory"><table><thead><tr><th>MALZEME / RAF</th><th>FİZİKSEL STOK</th><th>KULLANILABİLİR</th><th>DEPO / TARİH</th><th>DURUM</th><th>İŞLEM</th></tr></thead><tbody id="stock-rows">${stockRows()}</tbody></table></div><p class="note">Kullanılabilir = tarihi geçmemiş fiziksel stok − planlanan üretime ayrılan miktar. Tamamlanan üretimde tarihi en yakın uygun parti önce tüketilir.</p><div class="stock-aside"><section class="panel"><div class="section-head" style="margin-top:0"><h2>Önce bunları kullan</h2><span class="eyebrow">3 GÜN</span></div>${state.products.filter(soon).map(p=>`<div class="mini-row"><div>${p.name}<small>${p.zone}</small></div><button class="link" data-action="product" data-id="${p.id}">Partileri gör ↗</button></div>`).join('')||'<p>Yakın tarihli bir malzeme bulunmuyor.</p>'}</section><section class="panel" style="background:#e8d8c0"><span class="eyebrow">STOK KONTROLÜ</span><h2 style="margin-top:16px">Her hareketin<br>bir kaydı var.</h2><p>Mal kabulde tedarikçi ve tarih ekle. Malzemenin “Yönet” ekranından sayım düzelt, alt sınırı belirle veya rafını değiştir.</p><button class="btn light" data-action="receive">Yeni teslimat kaydet</button></section></div><div class="section-head"><h2>Son stok hareketleri</h2><button class="link" data-action="export">Kayıtları indir ↗</button></div><div class="table-wrap"><table><thead><tr><th>ZAMAN</th><th>MALZEME</th><th>MİKTAR</th><th>AÇIKLAMA</th></tr></thead><tbody>${movementsTable()}</tbody></table></div>`}
function filteredRecipes(){return recipes.filter(r=>(recipeCat==='Tümü'||r.category===recipeCat)&&(!menuOnly||state.menu.includes(r.id))&&r.name.toLocaleLowerCase('en-GB').includes(search.toLocaleLowerCase('en-GB')))}
function recipeView(){return heading('PASTANE MENÜSÜ / 12 REÇETE','Reçete defteri.','Viyana hamurları, tartlar, şu hamurları, kekler ve kurabiyeler. Her reçetede parti ölçüleri, malzeme kontrolü ve hazırlık adımları.')+`<div class="toolbar"><input class="search" id="recipe-search" aria-label="Reçete ara" placeholder="Kruvasan, ekler, limonlu tart…" value="${esc(search)}"><button class="chip ${menuOnly?'selected':''}" data-action="menu-filter">${menuOnly?'✓ ':''}Yalnızca vitrin menüsü</button></div><div class="chips" style="margin-bottom:25px">${['Tümü',...new Set(recipes.map(r=>r.category))].map(c=>`<button class="chip ${recipeCat===c?'selected':''}" data-action="recipe-category" data-id="${c}">${c}</button>`).join('')}</div><div id="recipe-results">${recipeCards(filteredRecipes())}</div><p class="note">Örnek eğitim reçeteleri. Süreler fırına, ekipmana ve ortam koşullarına göre değişir; dinlendirme ve mayalama süreleri toplam süreye dahildir. Su temel mutfak girdisi olarak stok takibine dahil edilmemiştir.</p>`}
function elapsed(j,now=Date.now()){if(!j.started)return 0;return Math.max(0,(now-j.started-(j.pausedTotal||0)-(j.pausedAt?now-j.pausedAt:0))/1000)}
function stageElapsed(j,now=Date.now()){if(!j.stageAt)return 0;return Math.max(0,(now-j.stageAt-(j.stagePaused||0)-(j.pausedAt?now-j.pausedAt:0))/1000)}
const clock=s=>{s=Math.floor(s);let h=Math.floor(s/3600),m=Math.floor(s%3600/60);return (h?h+':':'')+String(m).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};
function stageTarget(j){let r=recipeBy(j.recipe),restBefore=['croissant','pain','cinnamon','cookie','scone'].includes(r.id);return j.stage===1?r.times[0]+(restBefore?r.rest:0):j.stage===2?r.times[1]:r.times[2]+(!restBefore?r.rest:0)}
function jobCard(j){let r=recipeBy(j.recipe),target=stageTarget(j);return `<article class="job-card"><span class="eyebrow">${esc(j.note||'VİTRİN ÜRETİMİ')}</span><h3>${r.name}</h3><p>${j.batches} parti · ${j.batches*r.yield} ${r.unit} · ${esc(j.owner)}</p>${j.stage?`<span class="timer" data-timer="${j.id}">${clock(stageElapsed(j))}</span><p>${j.pausedAt?'Ⅱ Duraklatıldı':'Aşama süresi'} · Hedef ${target} dk</p><div class="progress"><span data-progress="${j.id}" style="width:${Math.min(100,stageElapsed(j)/Math.max(1,target*60)*100)}%"></span></div>`:'<p>Malzemeler ayrıldı.<br>Başlayınca süre takibi açılır.</p>'}<button class="btn" data-action="advance" data-id="${j.id}" ${j.pausedAt?'disabled':''}>${['Hazırlığa başla →','Fırına gönder →','Soğutma & süsleme →','Tamamla · stoktan düş ✓'][j.stage]}</button><div class="job-minor">${j.stage?`<button class="link" data-action="pause" data-id="${j.id}">${j.pausedAt?'Devam et':'Duraklat'}</button>`:''}<button class="link" data-action="job-detail" data-id="${j.id}">Ayrıntı ↗</button></div></article>`}
function filteredJobs(){return state.jobs.filter(j=>prepFilter==='Tümü'||j.owner===prepFilter)}
function prepView(){let active=state.jobs.filter(j=>j.stage>0),baking=state.jobs.filter(j=>j.stage===2),completed=state.history.filter(j=>!j.cancelled);return heading('GÜNLÜK ÜRETİM PANOSU','Pastanenin ritmi.','Partileri planla, iş istasyonları arasında ilerlet ve hazırlık süresini kaydet.',`<button class="btn" data-action="new-job">＋ Üretim planla</button>`)+summary([['Planlanan parti',state.jobs.filter(j=>j.stage===0).length,'Malzemeleri ayrıldı'],['Üretimde',active.length,'Hazırlık, fırın ve son dokunuş'],['Fırındaki parti',baking.reduce((a,j)=>a+j.batches,0),'Aktif pişirme partisi','warning'],['Tamamlanan',completed.length,'Kaydedilen üretim partisi']])+`<div class="toolbar"><span class="eyebrow">SORUMLUYA GÖRE</span><select id="prep-filter" aria-label="Üretim sorumlusu">${['Tümü',...new Set(state.jobs.map(j=>j.owner))].map(o=>`<option ${o===prepFilter?'selected':''}>${esc(o)}</option>`).join('')}</select><span class="note" style="margin:0">Adım ilerletmek için karttaki düğmeyi kullan.</span></div><div class="board">${stages.map((s,i)=>{let jobs=filteredJobs().filter(j=>j.stage===i);return `<section class="column"><div class="column-head"><h3>${s}</h3><span class="count">${jobs.length.toString().padStart(2,'0')}</span></div>${jobs.map(jobCard).join('')||'<div class="empty" style="padding:24px 10px">Bu aşamada parti yok.</div>'}</section>`}).join('')}</div><p class="note">Sayaçlar önerilen süreleri gösterir; aşamalar kendiliğinden ilerlemez. Duraklatılan süre toplamdan çıkarılır. Üretim tamamlanana kadar malzemeler ayrılmış kalır; iptal edilirse tekrar kullanılabilir olur.</p><div class="section-head"><h2>Üretim günlüğü</h2><button class="link" data-action="export">Kayıtları indir ↗</button></div><div class="table-wrap"><table><thead><tr><th>ÜRÜN / NOT</th><th>MİKTAR</th><th>GERÇEK / HEDEF SÜRE</th><th>SONUÇ</th><th>TARİH</th></tr></thead><tbody>${state.history.map(j=>{let r=recipeBy(j.recipe);return `<tr><td>${r.name}<small>${esc(j.note||'Vitrin üretimi')}</small></td><td>${j.batches*r.yield} ${r.unit}</td><td>${num((j.elapsed||0)/60)} dk / ${totalMinutes(r)} dk</td><td><span class="status ${j.cancelled?'neutral':''}">${j.cancelled?'İptal edildi':'Tamamlandı'}</span></td><td>${timeLabel(j.end)}</td></tr>`}).join('')||'<tr><td colspan="5">Tamamlanan veya iptal edilen üretimler burada görünecek.</td></tr>'}</tbody></table></div>`}
const stations=[
{id:'receiving',name:'Mal kabul',icon:'↘',desc:'Teslimatı kontrol et, tedarikçi ve parti tarihleriyle stoğa ekle.',zone:null,tip:'Miktar, ambalaj ve ürün tarihini kontrol et. Eksik veya hasarlı ürünleri teslimat notuna yaz.'},
{id:'dry',name:'Kuru depo',icon:'▤',zone:'Kuru depo',desc:'Un, şeker, çikolata ve kuru ürün rafları.',tip:'Ürün etiketini ve saklama talimatını takip et. Rafları kuru ve düzenli tut.'},
{id:'cold',name:'Buzdolabı',icon:'❄',zone:'Buzdolabı',desc:'Tereyağı, krema, yumurta ve taze meyveler.',tip:'Üretici saklama talimatlarına göre yerleştir. Açılan ürünleri etiketle; yakın tarihli partileri öne al.'},
{id:'frozen',name:'Dondurucu',icon:'❆',zone:'Dondurucu',desc:'Dondurulmuş meyveler ve yedek hamurlar.',tip:'Parti etiketlerini görünür tut. Çözündürme işlemini kurum prosedürüne göre planla.'},
{id:'prep',name:'Hamur & hazırlık',icon:'↺',stage:1,desc:'Tartım, yoğurma, katlama ve şekil verme tezgâhı.',tip:'Reçeteyi aç, malzemeleri tart ve alerjenler için ekipman ayrımını kontrol et.'},
{id:'oven',name:'Fırın & pişirme',icon:'♨',stage:2,desc:'Fırında pişen partiler ve aşama süreleri.',tip:'Fırın ayarını reçeteden kontrol et. Pişirme sırasında ürünün renk ve doku gelişimini takip et.'},
{id:'finish',name:'Soğutma & süsleme',icon:'✳',stage:3,desc:'Tel raflar, dolgu, glazür ve son kalite kontrolü.',tip:'Pişen ürünleri uygun şekilde soğut. Dolgu ve kaplamaları reçetedeki sırayla uygula.'},
{id:'display',name:'Vitrin & servis',icon:'▱',desc:'Günün menüsü ve tamamlanan üretimler.',tip:'Ürün adı ve alerjen bilgisini kontrol et. Saklama koşuluna uygun vitrinde sergile.'}
];
function stationCount(s){return s.zone?state.products.filter(p=>p.zone===s.zone).length:s.stage?state.jobs.filter(j=>j.stage===s.stage).length:s.id==='display'?state.menu.length:state.movements.filter(m=>m.type==='receipt').length}
function planView(){return heading('ATÖLYE YERLEŞİMİ / 8 ALAN','Mal kabulden vitrine.','Bir alana dokun: içerideki malzemeleri, aktif işleri ve ilgili işlemleri aç.',`<button class="btn light" data-action="new-job">Üretim planla ↗</button>`)+`<div class="legend"><span><b style="background:var(--sage)"></b>Depolama</span><span><b></b>Hazırlık</span><span><b style="background:var(--yellow)"></b>Pişirme</span><span><b style="background:var(--blue)"></b>Soğutma</span></div><div class="plan-shell"><section class="floorplan" aria-label="Etkileşimli pastane yerleşim planı">${stations.map((s,i)=>`<button class="station ${selectedStation===s.id?'active':''}" data-action="station" data-id="${s.id}"><span class="eyebrow">0${i+1} / ${s.icon}</span><h3>${s.name}</h3><small>${s.id==='receiving'?'Teslimat & kontrol':s.zone?'Raflar & malzemeler':s.id==='display'?'Günün menüsü':'Üretim istasyonu'}</small><span class="station-bottom"><span>${stationCount(s)} ${s.zone?'malzeme':s.id==='display'?'ürün':s.id==='receiving'?'teslimat':'iş'}</span><span>Alanı aç ↗</span></span></button>`).join('')}</section><aside class="plan-guide"><div><span class="eyebrow">PASTANENİN AKIŞI</span><h3>Her adımın<br>bir yeri var.</h3><p>Depo alanından ürünü, üretim alanından aktif partiyi açabilirsin.</p></div><ol><li>Teslim al ve depola</li><li>Tart, hazırla ve şekillendir</li><li>Fırınla</li><li>Soğut, süsle ve kontrol et</li><li>Vitrine al</li></ol></aside></div><p class="note">Kavramsal pastane yerleşimi. Alanları tıklayarak açılan detaylar stok ve üretim kayıtlarıyla bağlantılıdır.</p>`}
function render(){document.title='culinaryFLOW · '+(navs.find(n=>n[0]===page)?.[1]||'Pastane Atölyesi');$('#navigation').innerHTML=navs.map(([id,n])=>`<a href="#${id}" ${page===id?'class="current" aria-current="page"':''}>${n}</a>`).join('');$('#app').innerHTML=({overview,stock:stockView,recipes:recipeView,prep:prepView,plan:planView}[page]||overview)();tick()}
function showModal(title,body){let m=$('#modal');m.innerHTML=`<div class="modal-top"><span class="eyebrow">${title}</span><button class="close" data-action="close" aria-label="Pencereyi kapat">×</button></div><div class="modal-content">${body}</div>`;if(!m.open)m.showModal();m.scrollTop=0}
function closeModal(){$('#modal').close();currentRecipe=null;currentProduct=null}
function ingredientHTML(r,b){return r.ingredients.map(([id,q])=>{let p=productBy(id),ok=available(p)+1e-6>=q*b;return `<div class="ingredient-row ${ok?'':'missing'}"><div>${p.name}<small>${p.zone} · ${p.shelf}</small></div><div style="text-align:right">${qty(q*b,p.unit)}<small>${ok?'Stok uygun':'Eksik: '+qty(Math.max(0,q*b-available(p)),p.unit)}</small></div></div>`}).join('')}
function recipeDetail(id,b=1){let r=recipeBy(id);if(!r)return;currentRecipe=id;scaleBatches=b;showModal('REÇETE DEFTERİ / '+r.category,`<div class="recipe-detail-top"><div><span class="eyebrow">${r.category}</span><h2>${r.name}</h2><p class="recipe-description">${r.desc}</p><div class="recipe-detail-meta"><span class="status neutral">${r.yield} ${r.unit} / parti</span><span class="status neutral">${totalMinutes(r)} dk toplam</span></div><p class="note">Hazırlık ${r.times[0]} dk · Pişirme ${r.times[1]} dk · Son işlem ${r.times[2]} dk${r.rest?' · Dinlendirme / mayalama '+r.rest+' dk':''}</p></div>${art(r)}</div><div class="scale-input"><label for="recipe-scale">Üretim miktarı</label><input type="number" id="recipe-scale" min="1" max="20" step="1" value="${b}"><span>parti → <b id="recipe-yield">${b*r.yield} ${r.unit}</b></span></div><div class="recipe-detail-columns"><section class="ingredient-list"><h3>Malzeme listesi</h3><div id="scaled-ingredients">${ingredientHTML(r,b)}</div><p class="note">Alerjenler: ${r.allergens}. Tedarikçi etiketlerini ayrıca kontrol et.</p></section><section><h3>Adım adım hazırlık</h3><p class="note">Adımlar 1 parti içindir. Çoklu üretimde yukarıdaki toplam malzeme ölçülerini kullan; şekillendirme ve tepsi düzenini her parti için tekrarla.</p>${r.steps.map(([t,d],i)=>`<div class="recipe-step"><span class="step-number">${i+1}</span><div><span class="eyebrow">${t}</span><p>${d}</p></div></div>`).join('')}</section></div><div class="modal-actions"><button class="btn" data-action="plan-recipe" data-id="${r.id}">Bu reçeteyi üretime al →</button><button class="btn light" data-action="toggle-menu" data-id="${r.id}">${state.menu.includes(r.id)?'Vitrin menüsünden çıkar':'Vitrin menüsüne ekle'}</button></div><p class="note">Ölçüler örnek eğitim reçetesidir. Dinlendirme ve mayalama aşamaları ürünün kıvamı ve hacmi kontrol edilerek tamamlanır.</p>`)}
function recipeOptions(sel){return recipes.map(r=>`<option value="${r.id}" ${sel===r.id?'selected':''}>${r.name} · ${r.yield} ${r.unit}/parti</option>`).join('')}
function productionForm(id='croissant',b=1){let r=recipeBy(id);showModal('ÜRETİM PLANLAMA',`<h2>Bir sonraki tepsi.</h2><p>Reçeteyi ve parti sayısını seç. Planlanan üretim için malzemeler hemen ayrılır.</p><form id="job-form"><div class="form-grid"><label class="full">Reçete<select name="recipe" id="job-recipe">${recipeOptions(id)}</select></label><label>Parti sayısı<input name="batches" id="job-batches" type="number" min="1" max="20" step="1" value="${b}" required></label><label>Sorumlu<input name="owner" maxlength="50" required value="Bakery team"></label><label class="full">Üretim notu<input name="note" maxlength="100" placeholder="Örn. Sabah vitrini / 10.00 teslim"></label></div><div id="production-check" class="form-result">${productionCheck(r,b)}</div><p class="form-error" id="form-error" role="alert"></p><button class="btn" type="submit">Planla & malzemeleri ayır</button></form>`)}
function productionCheck(r,b){return `<b>${r.yield*b} ${r.unit} · ${totalMinutes(r)} dk hedef toplam</b><p>${canMake(r,b)?'✓ Malzemeler bu üretim için yeterli.':r.ingredients.filter(([id,q])=>available(productBy(id))+1e-6<q*b).map(([id,q])=>`${productBy(id).name}: ${qty(q*b-available(productBy(id)),productBy(id).unit)} eksik`).join('<br>')}</p>`}
function addJob(data){let r=recipeBy(data.recipe),b=Number(data.batches);if(!r||!Number.isInteger(b)||b<1||b>20)return'Geçerli bir reçete ve 1–20 arasında tam parti sayısı gir.';if(!String(data.owner||'').trim())return'Üretim sorumlusunu yaz.';if(!canMake(r,b))return'Bu parti için yeterli kullanılabilir stok yok. Önce mal kabul yap veya parti sayısını azalt.';state.jobs.push({id:uid(),recipe:r.id,batches:b,stage:0,owner:String(data.owner).trim().slice(0,50),note:String(data.note||'').trim().slice(0,100),created:Date.now(),started:null,stageAt:null,pausedAt:null,pausedTotal:0,stagePaused:0,checks:[],transitions:[]});save();return null}
function addMovement(product,change,type,reason){state.movements.unshift({id:uid(),product,change:+change.toFixed(3),type,reason,at:Date.now()})}
function advanceJob(id){let j=state.jobs.find(x=>x.id===id);if(!j)return'Üretim bulunamadı.';if(j.pausedAt)return'Önce duraklatılan üretimi devam ettir.';let now=Date.now(),r=recipeBy(j.recipe);if(j.stage===3){if(!['baked','portion','label'].every(c=>j.checks.includes(c))){jobDetail(id,true);return'Üretimi bitirmek için son kalite kontrol listesini tamamla.'}let shortage=r.ingredients.find(([pid,q])=>usable(productBy(pid))+1e-6<q*j.batches);if(shortage)return productBy(shortage[0]).name+' için uygun tarihli stok yetersiz. Mal kabulü kontrol et.';for(let [pid,q]of r.ingredients){let p=productBy(pid),remaining=q*j.batches;let lots=p.lots.filter(l=>l.expiry>=today()&&l.qty>0).sort((a,b)=>a.expiry.localeCompare(b.expiry));for(let l of lots){let used=Math.min(l.qty,remaining);l.qty=+(l.qty-used).toFixed(3);remaining=+(remaining-used).toFixed(3);if(remaining<=1e-6)break}addMovement(pid,-q*j.batches,'production',r.name+' · '+j.batches+' parti')}state.history.unshift({...j,end:now,elapsed:elapsed(j,now),cancelled:false});state.jobs=state.jobs.filter(x=>x.id!==id);save();return null}
j.transitions.push({stage:j.stage,at:now,seconds:stageElapsed(j,now)});j.stage++;if(!j.started)j.started=now;j.stageAt=now;j.stagePaused=0;save();return null}
function togglePause(id){let j=state.jobs.find(x=>x.id===id);if(!j||!j.stage)return;let now=Date.now();if(j.pausedAt){let duration=now-j.pausedAt;j.pausedTotal+=duration;j.stagePaused+=duration;j.pausedAt=null}else j.pausedAt=now;save()}
function jobDetail(id,finish=false){let j=state.jobs.find(x=>x.id===id);if(!j)return;let r=recipeBy(j.recipe);showModal('ÜRETİM PARTİSİ / '+stages[j.stage],`<div class="recipe-detail-top"><div><h2>${r.name}</h2><p class="recipe-description">${j.batches} parti · ${j.batches*r.yield} ${r.unit}<br>${esc(j.owner)} · ${esc(j.note||'Vitrin üretimi')}</p><span class="status info">${j.pausedAt?'Duraklatıldı':stages[j.stage]}</span></div>${art(r)}</div><div class="modal-flow">${stages.map((s,i)=>`<span class="${i===j.stage?'current':''}">${i<j.stage?'✓ ':''}${s}</span>`).join('')}</div><div class="modal-summary"><div>Geçen üretim süresi<strong data-total-timer="${j.id}">${clock(elapsed(j))}</strong></div><div>Bu aşama<strong data-timer="${j.id}">${clock(stageElapsed(j))}</strong></div><div>Hedef toplam<strong>${totalMinutes(r)} dk</strong></div></div><p class="note">${j.stage?stageAreas[j.stage]:'Planlanan üretim'} · Açılış: ${timeLabel(j.created)}</p>${j.stage===3?`<div class="ingredient-list"><h3>Son kalite kontrolü</h3><p class="note">Üretimi tamamlamak için üç kontrolü de işaretle.</p><div class="checklist">${[['baked','Pişme, doku ve görünüm kontrol edildi'],['portion','Porsiyon / adet sayısı kontrol edildi'],['label','Alerjen, saklama ve vitrin etiketi kontrol edildi']].map(([c,t])=>`<label><input type="checkbox" data-check-job="${j.id}" value="${c}" ${j.checks.includes(c)?'checked':''}>${t}</label>`).join('')}</div></div>`:''}<div class="modal-actions"><button class="btn" data-action="advance" data-id="${j.id}" ${j.pausedAt?'disabled':''}>${['Hazırlığa başla','Fırına gönder','Soğutma & süslemeye al','Üretimi tamamla & stoktan düş'][j.stage]}</button>${j.stage?`<button class="btn light" data-action="pause" data-id="${j.id}">${j.pausedAt?'Devam et':'Duraklat'}</button>`:''}<button class="btn light" data-action="recipe" data-id="${r.id}">Reçeteyi aç</button><button class="btn danger" data-action="cancel-confirm" data-id="${j.id}">Partiyi iptal et</button></div><p id="modal-error" class="form-error" role="alert">${finish?'Tamamlamadan önce kalite kontrolünü işaretle.':''}</p><p class="note">İptal edilen partiler malzeme tüketmez ve ayrılan miktarlar serbest bırakılır. Kullanılan veya ziyan olan malzemeyi ayrıca stok sayımıyla kaydedebilirsin.</p>`)}
function cancelConfirm(id){let j=state.jobs.find(x=>x.id===id);if(!j)return;showModal('PARTİYİ İPTAL ET',`<h2>${recipeBy(j.recipe).name}</h2><p>Bu partinin üretimi iptal edilecek. Ayrılan malzemeler serbest bırakılacak; kayıt üretim günlüğünde korunacak.</p><p class="note">Fiilen tüketilmiş malzemeleri “Stok & depo → Yönet → Sayım” üzerinden ayrıca kaydet.</p><div class="modal-actions"><button class="btn danger" data-action="cancel-job" data-id="${j.id}">İptali kaydet</button><button class="btn light" data-action="job-detail" data-id="${j.id}">Geri dön</button></div>`)}
function productDetail(id){let p=productBy(id);if(!p)return;currentProduct=id;let related=recipes.filter(r=>r.ingredients.some(x=>x[0]===id));showModal('MALZEME / '+p.zone,`<span class="eyebrow">${p.shelf}</span><h2>${p.name}</h2>${badge(p)}<div class="modal-summary"><div>Fiziksel stok<strong>${qty(total(p),p.unit)}</strong></div><div>Üretime ayrılan<strong>${qty(reserved(id),p.unit)}</strong></div><div>Kullanılabilir<strong>${qty(available(p),p.unit)}</strong></div></div><div class="modal-actions"><button class="btn" data-action="receive" data-id="${p.id}">＋ Teslimat ekle</button><button class="btn light" data-action="count" data-id="${p.id}">Sayım / düzeltme</button><button class="btn light" data-action="settings" data-id="${p.id}">Raf & alt sınır</button></div><h3>Stok partileri</h3><p class="note">Üretimde son kullanım tarihi en yakın uygun parti önce kullanılır. Tarihi geçen parti kullanılabilir stoktan hariç tutulur.</p>${p.lots.filter(l=>l.qty>0).sort((a,b)=>a.expiry.localeCompare(b.expiry)).map(l=>`<div class="lot"><div><b>${qty(l.qty,p.unit)}</b><br><span class="note">${esc(l.supplier)} · Giriş ${dateLabel(l.received)}</span></div><div style="text-align:right">SKT ${dateLabel(l.expiry)}<br><span class="status ${l.expiry<today()?'bad':l.expiry<=future(3)?'warn':''}">${l.expiry<today()?'Kullanıma kapalı':l.expiry<=future(3)?'Önce kullan':'Uygun'}</span></div></div>`).join('')||'<div class="empty">Fiziksel stok bulunmuyor.</div>'}<hr class="divider"><h3>Bu malzemeyi kullanan reçeteler</h3><div class="chips" style="margin-top:18px">${related.map(r=>`<button class="chip" data-action="recipe" data-id="${r.id}">${r.name} ↗</button>`).join('')||'<span class="note">Henüz bir reçetede kullanılmıyor.</span>'}</div><hr class="divider"><h3>Son hareketler</h3>${state.movements.filter(m=>m.product===id).slice(0,5).map(m=>`<div class="mini-row"><div>${esc(m.reason)}<small>${timeLabel(m.at)}</small></div><span>${m.change>0?'+':''}${qty(m.change,p.unit)}</span></div>`).join('')||'<p class="note">Açılış stoğundan sonra hareket kaydedilmedi.</p>'}`)}
function receiveForm(id='flour'){let p=productBy(id)||state.products[0];showModal('MAL KABUL / YENİ TESLİMAT',`<h2>Yeni bir teslimat.</h2><p>Malzemeyi seç, teslim alınan miktarı ve parti bilgilerini kaydet.</p><form id="receive-form"><div class="form-grid"><label class="full">Malzeme<select id="receive-product" name="product">${state.products.map(s=>`<option value="${s.id}" ${p.id===s.id?'selected':''}>${s.name} · ${s.unit}</option>`).join('')}</select></label><label>Miktar (<span id="receive-unit">${p.unit}</span>)<input type="number" name="amount" min="0.001" step="0.001" required placeholder="Örn. ${p.unit==='adet'?'24':'1000'}"></label><label>Son kullanım tarihi<input name="expiry" type="date" required min="${today()}" value="${future(14)}"></label><label class="full">Tedarikçi<input name="supplier" required maxlength="80" placeholder="Tedarikçi / teslimat adı"></label><label class="full">Teslimat notu<input name="note" maxlength="120" placeholder="Örn. Ambalaj ve miktar kontrol edildi"></label></div><div class="form-result" id="receive-location">Yerleştirilecek alan: <b>${p.zone} · ${p.shelf}</b><br>Mevcut stok: ${qty(total(p),p.unit)}</div><p class="form-error" id="form-error" role="alert"></p><button class="btn" type="submit">Teslimatı stoğa kaydet</button><p class="note">Miktarı ürünün biriminde gir: 1 kg = 1000 g, 1 L = 1000 ml.</p></form>`)}
function receive(data){let p=productBy(data.product),amount=+data.amount;if(!p||!Number.isFinite(amount)||amount<=0)return'Geçerli bir malzeme ve pozitif miktar gir.';if(p.unit==='adet'&&!Number.isInteger(amount))return'Adet miktarı tam sayı olmalı.';if(!/^\d{4}-\d{2}-\d{2}$/.test(data.expiry)||data.expiry<today())return'Tarihi geçmiş mal kabulü kaydedilemez.';if(!String(data.supplier||'').trim())return'Tedarikçi bilgisini yaz.';p.lots.push({id:uid(),qty:amount,received:today(),expiry:data.expiry,supplier:String(data.supplier).trim().slice(0,80)});addMovement(p.id,amount,'receipt','Mal kabul · '+String(data.supplier).trim()+(data.note?' · '+String(data.note).slice(0,120):''));save();return null}
function countForm(id){let p=productBy(id);showModal('SAYIM / STOK DÜZELTME',`<h2>${p.name}</h2><p>Bir stok partisi seç ve o partide saydığın fiziksel miktarı gir. Değişiklik açıklaması hareket kaydına işlenir.</p><form id="count-form"><input type="hidden" name="product" value="${p.id}"><div class="form-grid"><label class="full">Sayılacak stok partisi<select name="lot" id="count-lot">${p.lots.map(l=>`<option value="${l.id}">SKT ${dateLabel(l.expiry)} · ${qty(l.qty,p.unit)} · ${esc(l.supplier)}</option>`).join('')}</select></label><label>Bu partide sayılan miktar (${p.unit})<input name="amount" id="count-amount" type="number" min="0" step="0.001" required value="${p.lots[0]?.qty||0}"></label><label>Düzeltme nedeni<select name="reason"><option>Fiziksel sayım farkı</option><option>Fire / kırılma</option><option>Tarihi geçmiş ürün ayrıldı</option><option>Diğer düzeltme</option></select></label></div><div class="form-result">Aktif üretime toplam <b>${qty(reserved(p.id),p.unit)}</b> ayrıldı. Düzeltme, üretime ayrılan kullanılabilir stoktan aşağıya inemez.</div><p class="form-error" id="form-error" role="alert"></p><button class="btn" type="submit">Sayımı kaydet</button></form>`)}
function countStock(data){let p=productBy(data.product),l=p?.lots.find(l=>l.id===data.lot),amount=+data.amount;if(!l||!Number.isFinite(amount)||amount<0)return'Geçerli bir parti ve sıfır veya pozitif miktar gir.';if(p.unit==='adet'&&!Number.isInteger(amount))return'Adet miktarı tam sayı olmalı.';let usableAfter=usable(p)+(l.expiry>=today()?amount-l.qty:0);if(usableAfter+1e-6<reserved(p.id))return'Aktif üretim için ayrılan miktar korunmalı. Önce ilgili üretimi iptal et veya uygun tarihli stok ekle.';let diff=amount-l.qty;if(Math.abs(diff)<.0001)return'Sayılan miktar mevcut kayıtla aynı.';l.qty=amount;addMovement(p.id,diff,'adjustment',data.reason);save();return null}
function settingsForm(id){let p=productBy(id);showModal('DEPOLAMA & UYARI AYARLARI',`<h2>${p.name}</h2><form id="settings-form"><input type="hidden" name="product" value="${p.id}"><div class="form-grid"><label>Depolama alanı<select name="zone">${zones.map(z=>`<option ${z===p.zone?'selected':''}>${z}</option>`).join('')}</select></label><label>Raf / konum<input name="shelf" maxlength="70" required value="${esc(p.shelf)}"></label><label>Minimum kullanılabilir stok (${p.unit})<input type="number" name="min" min="0" step="0.001" required value="${p.min}"></label></div><p class="note">Depolama alanını ürün etiketi ve pastanenin prosedürlerine uygun seç.</p><p class="form-error" id="form-error" role="alert"></p><button class="btn" type="submit">Ayarları kaydet</button></form>`)}
function shoppingList(){let low=lowProducts();showModal('SATIN ALMA / EKSİK LİSTESİ',`<h2>Bir sonraki teslimat için.</h2><p>Alt sınıra ulaşmak için gereken miktarlar. Planlanmış üretim için ayrılanlar hesaba katılır.</p>${low.map(p=>`<div class="mini-row"><div><b>${p.name}</b><small>Kullanılabilir ${qty(available(p),p.unit)} · Alt sınır ${qty(p.min,p.unit)}</small></div><button class="link" data-action="receive" data-id="${p.id}">＋ ${qty(p.min-available(p),p.unit)}</button></div>`).join('')||'<div class="empty">Eksik malzeme yok.</div>'}<div class="modal-actions"><button class="btn light" data-action="download-shopping">Listeyi indir ↗</button></div>`)}
function stationDetail(id){let s=stations.find(s=>s.id===id);if(!s)return;selectedStation=id;if(page==='plan')render();let products=s.zone?state.products.filter(p=>p.zone===s.zone):[],jobs=s.stage?state.jobs.filter(j=>j.stage===s.stage):[];let body=`<span class="eyebrow">0${stations.indexOf(s)+1} / PASTANE ALANI</span><h2>${s.name}</h2><p>${s.desc}</p><div class="select-hint">${s.tip}</div>`;if(s.id==='receiving')body+=`<div class="modal-actions"><button class="btn" data-action="receive">＋ Teslimat kaydet</button><button class="btn light" data-action="shopping-list">Eksik malzemeleri gör</button></div><h3>Son teslimatlar</h3>${state.movements.filter(m=>m.type==='receipt').slice(0,5).map(m=>`<div class="mini-row"><div>${productBy(m.product).name}<small>${esc(m.reason)} · ${timeLabel(m.at)}</small></div><b>＋ ${qty(m.change,productBy(m.product).unit)}</b></div>`).join('')||'<p class="note">Henüz yeni teslimat kaydedilmedi.</p>'}`;if(s.zone)body+=`<div class="modal-summary"><div>Malzeme<strong>${products.length}</strong></div><div>Stok uyarısı<strong>${products.filter(p=>available(p)<p.min).length}</strong></div><div>Yakın tarih<strong>${products.filter(soon).length}</strong></div></div>${products.map(p=>`<div class="mini-row"><div>${p.name}<small>${p.shelf} · Kullanılabilir ${qty(available(p),p.unit)}</small></div><button class="link" data-action="product" data-id="${p.id}">Malzemeyi aç ↗</button></div>`).join('')}<div class="modal-actions"><button class="btn light" data-action="open-zone" data-id="${s.zone}">Bu alanı stok ekranında aç →</button></div>`;if(s.stage)body+=`<div class="section-head"><h3>Bu alandaki işler</h3><span class="status info">${jobs.length} parti</span></div>${jobs.map(j=>`<div class="mini-row"><div>${recipeBy(j.recipe).name}<small>${j.batches*recipeBy(j.recipe).yield} ${recipeBy(j.recipe).unit} · ${esc(j.owner)}</small></div><button class="link" data-action="job-detail" data-id="${j.id}">İşi aç ↗</button></div>`).join('')||'<div class="empty">Bu alanda aktif üretim yok.</div>'}<div class="modal-actions"><button class="btn" data-action="new-job">＋ Üretim planla</button><button class="btn light" data-action="go-prep">Üretim panosunu aç →</button></div>`;if(s.id==='display')body+=`<div class="modal-summary"><div>Menüde<strong>${state.menu.length}</strong></div><div>Tamamlanan parti<strong>${state.history.filter(j=>!j.cancelled).length}</strong></div><div>Hazırlanan ürün<strong>${state.history.filter(j=>!j.cancelled).reduce((a,j)=>a+j.batches*recipeBy(j.recipe).yield,0)}</strong></div></div><h3>Vitrin menüsü</h3>${recipes.filter(r=>state.menu.includes(r.id)).map(r=>`<div class="mini-row"><div>${r.name}<small>${r.category} · Alerjen: ${r.allergens}</small></div><button class="link" data-action="recipe" data-id="${r.id}">Reçete ↗</button></div>`).join('')||'<p>Menüde ürün yok. Reçete ekranından ekle.</p>'}`;body+=`<hr class="divider"><label class="checklist"><span><input type="checkbox" data-station-check="${s.id}" ${state.stationChecks[s.id]===today()?'checked':''}> Bugünkü alan / ekipman kontrolü yapıldı</span></label><p class="note">Bu işaret günlük alan kontrolü için kaydedilir; ertesi gün yeniden işaretlenmesi gerekir.</p>`;showModal('ATÖLYE PLANI / ALAN DETAYI',body)}
function tick(){let now=Date.now();document.querySelectorAll('[data-timer]').forEach(el=>{let j=state.jobs.find(j=>j.id===el.dataset.timer);if(j)el.textContent=clock(stageElapsed(j,now))});document.querySelectorAll('[data-total-timer]').forEach(el=>{let j=state.jobs.find(j=>j.id===el.dataset.totalTimer);if(j)el.textContent=clock(elapsed(j,now))});document.querySelectorAll('[data-progress]').forEach(el=>{let j=state.jobs.find(j=>j.id===el.dataset.progress);if(j)el.style.width=Math.min(100,stageElapsed(j)/Math.max(1,stageTarget(j)*60)*100)+'%'})}
function download(name,content,type='application/json'){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function allExport(){download('culinaryFLOW-pastane-'+today()+'.json',JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2));toast('Pastane kayıtları indirildi.')}
function shoppingCSV(){let csv='\ufeffIngredient;Storage;Unit;Available;Minimum;Missing\n'+lowProducts().map(p=>[p.name,p.zone,p.unit,available(p),p.min,p.min-available(p)].join(';')).join('\n');download('culinaryFLOW-eksik-listesi.csv',csv,'text/csv;charset=utf-8')}
function formData(f){return Object.fromEntries(new FormData(f).entries())}
function formError(message){let el=$('#form-error');if(el)el.textContent=message||''}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;let a=b.dataset.action,id=b.dataset.id;
if(a==='close')closeModal();else if(a==='recipe')recipeDetail(id);else if(a==='new-job')productionForm(id||'croissant');else if(a==='plan-recipe'){let b=+$('#recipe-scale').value;if(!Number.isInteger(b)||b<1||b>20){toast('1–20 arasında tam parti sayısı gir.');return}productionForm(id,b)}else if(a==='receive')receiveForm(id);else if(a==='product')productDetail(id);else if(a==='count')countForm(id);else if(a==='settings')settingsForm(id);else if(a==='shopping-list')shoppingList();else if(a==='export')allExport();else if(a==='download-shopping')shoppingCSV();else if(a==='zone-filter'){stockZone=stockZone===id?'Tümü':id;render()}else if(a==='clear-stock'){stockZone=stockStatus='Tümü';search='';render()}else if(a==='recipe-category'){recipeCat=id;render()}else if(a==='menu-filter'){menuOnly=!menuOnly;render()}else if(a==='toggle-menu'){let i=state.menu.indexOf(id);if(i>=0)state.menu.splice(i,1);else state.menu.push(id);save();render();recipeDetail(id,scaleBatches);toast(i>=0?'Ürün vitrin menüsünden çıkarıldı.':'Ürün vitrin menüsüne eklendi.')}else if(a==='advance'){let j=state.jobs.find(j=>j.id===id),old=j?.stage;let error=advanceJob(id);if(error){toast(error);if($('#modal-error'))$('#modal-error').textContent=error;return}render();if($('#modal').open){let exists=state.jobs.some(j=>j.id===id);if(exists)jobDetail(id);else closeModal()}toast(old===3?'Üretim tamamlandı; malzemeler stoktan düşüldü.':'Üretim bir sonraki aşamaya alındı.')}else if(a==='pause'){togglePause(id);render();if($('#modal').open)jobDetail(id)}else if(a==='job-detail')jobDetail(id);else if(a==='cancel-confirm')cancelConfirm(id);else if(a==='cancel-job'){let j=state.jobs.find(x=>x.id===id);if(!j)return;state.history.unshift({...j,cancelled:true,end:Date.now(),elapsed:elapsed(j)});state.jobs=state.jobs.filter(x=>x.id!==id);save();closeModal();render();toast('Parti iptal edildi; ayrılan malzemeler serbest.')}else if(a==='station')stationDetail(id);else if(a==='open-zone'){closeModal();history.replaceState(null,'','#stock');navigate('stock');stockZone=id;render()}else if(a==='go-prep'){closeModal();location.hash='prep';navigate('prep')}
});
document.addEventListener('input',e=>{let el=e.target;if(el.id==='stock-search'){search=el.value;$('#stock-rows').innerHTML=stockRows()}else if(el.id==='recipe-search'){search=el.value;$('#recipe-results').innerHTML=recipeCards(filteredRecipes())}else if(el.id==='recipe-scale'){let b=+el.value,r=recipeBy(currentRecipe);if(!Number.isInteger(b)||b<1||b>20)return;scaleBatches=b;$('#recipe-yield').textContent=b*r.yield+' '+r.unit;$('#scaled-ingredients').innerHTML=ingredientHTML(r,b)}else if(el.id==='job-batches'||el.id==='job-recipe'){let r=recipeBy($('#job-recipe').value),b=+$('#job-batches').value;$('#production-check').innerHTML=Number.isInteger(b)&&b>=1&&b<=20?productionCheck(r,b):'1–20 arasında tam parti sayısı gir.'}});
document.addEventListener('change',e=>{let el=e.target;if(el.id==='stock-zone'){stockZone=el.value;render()}else if(el.id==='stock-status'){stockStatus=el.value;render()}else if(el.id==='prep-filter'){prepFilter=el.value;render()}else if(el.id==='receive-product'){let p=productBy(el.value);$('#receive-unit').textContent=p.unit;$('#receive-location').innerHTML='Yerleştirilecek alan: <b>'+p.zone+' · '+esc(p.shelf)+'</b><br>Mevcut stok: '+qty(total(p),p.unit)}else if(el.id==='count-lot'){let p=productBy($('#count-form [name="product"]').value),l=p.lots.find(l=>l.id===el.value);$('#count-amount').value=l.qty}else if(el.dataset.checkJob){let j=state.jobs.find(j=>j.id===el.dataset.checkJob);if(!j)return;j.checks=j.checks.filter(c=>c!==el.value);if(el.checked)j.checks.push(el.value);save()}else if(el.dataset.stationCheck){state.stationChecks[el.dataset.stationCheck]=el.checked?today():null;save()}});
document.addEventListener('submit',e=>{let f=e.target;if(!['job-form','receive-form','count-form','settings-form'].includes(f.id))return;e.preventDefault();let d=formData(f),error=null;if(f.id==='job-form')error=addJob(d);else if(f.id==='receive-form')error=receive(d);else if(f.id==='count-form')error=countStock(d);else{let p=productBy(d.product),min=+d.min;if(!p||!zones.includes(d.zone)||!String(d.shelf).trim()||!Number.isFinite(min)||min<0)error='Depolama alanını, rafı ve geçerli alt sınırı gir.';else{let old=p.zone+' · '+p.shelf;p.zone=d.zone;p.shelf=String(d.shelf).trim().slice(0,70);p.min=min;addMovement(p.id,0,'settings','Raf / alt sınır güncellendi · '+old+' → '+p.zone+' · '+p.shelf);save()}}if(error){formError(error);return}closeModal();if(f.id==='job-form'){location.hash='prep';navigate('prep')}else render();toast({'job-form':'Üretim planlandı; malzemeler ayrıldı.','receive-form':'Teslimat kaydedildi; stoklar güncellendi.','count-form':'Sayım kaydedildi.','settings-form':'Depolama ve uyarı ayarları güncellendi.'}[f.id])});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal()}});
setInterval(tick,1000);onRoute();save();
